public final class AudioFiles {
    private static int le(DataInputStream in)throws IOException{return Integer.reverseBytes(in.readInt());}
    private static void integer(OutputStream out,int n)throws IOException{out.write(n);out.write(n>>>8);out.write(n>>>16);out.write(n>>>24);}
    private static void shortInt(OutputStream out,int n)throws IOException{out.write(n);out.write(n>>>8);}
    public static float[] readWav(InputStream stream)throws IOException{DataInputStream in=new DataInputStream(new BufferedInputStream(stream));if(in.readInt()!=0x52494646)throw new IOException("Choose a PCM / float WAV");le(in);if(in.readInt()!=0x57415645)throw new IOException("Invalid WAV");int encoding=0,channels=0,rate=0,bits=0,align=0;byte[] audio=null;while(true){int tag;try{tag=in.readInt();}catch(EOFException e){break;}int length=le(in);if(length<0||length>100*1024*1024)throw new IOException("WAV exceeds import limit");byte[] bytes=new byte[length];in.readFully(bytes);if((length&1)!=0)in.readByte();ByteBuffer b=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);if(tag==0x666d7420&&length>=16){encoding=b.getShort()&65535;channels=b.getShort()&65535;rate=b.getInt();b.getInt();align=b.getShort()&65535;bits=b.getShort()&65535;if(encoding==65534&&length>=40)encoding=b.getShort(24)&65535;}if(tag==0x64617461){audio=bytes;break;}}
        if(audio==null||channels<1||channels>2||rate<8000||rate>192000||align!=channels*(bits/8)||!((encoding==1&&(bits==16||bits==24||bits==32))||(encoding==3&&bits==32)))throw new IOException("Use mono/stereo PCM 16/24/32 or float32 WAV");int frames=audio.length/align,target=(int)Math.round(frames*(double)LoopEngine.RATE/rate);if(target<1||target>LoopEngine.RATE*LoopEngine.MAX_SECONDS)throw new IOException("Import limit: 60 seconds");float[] src=new float[frames*2];ByteBuffer b=ByteBuffer.wrap(audio).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<frames;i++){for(int ch=0;ch<channels;ch++){float f;if(encoding==3)f=b.getFloat();else if(bits==16)f=b.getShort()/32768f;else if(bits==24){int n=(b.get()&255)|((b.get()&255)<<8)|(b.get()<<16);f=n/8388608f;}else f=(float)(b.getInt()/2147483648.0);if(!Float.isFinite(f))throw new IOException("Nonfinite audio");src[i*2+ch]=f;}if(channels==1)src[i*2+1]=src[i*2];}if(rate==LoopEngine.RATE)return src;float[] dst=new float[target*2];double scale=rate/(double)LoopEngine.RATE,cut=Math.min(1,1/scale)*.95;for(int i=0;i<target;i++){double p=i*scale;int center=(int)p;double norm=0,l=0,r=0;for(int k=-24;k<=24;k++){int j=Math.max(0,Math.min(frames-1,center+k));double x=p-(center+k),s=Math.abs(x)<1e-9?cut:Math.sin(Math.PI*x*cut)/(Math.PI*x),w=.5+.5*Math.cos(Math.PI*x/25);s*=w;norm+=s;l+=src[j*2]*s;r+=src[j*2+1]*s;}dst[i*2]=(float)(l/norm);dst[i*2+1]=(float)(r/norm);}return dst;
    }
    public static LoopEngine snapshot(LoopEngine source,int bank){LoopEngine e=new LoopEngine();e.limitOutput=false;synchronized(source){LoopEngine.Bank from=source.banks[bank],to=e.banks[0];to.origin=from.origin;to.frame=from.origin;to.warp=from.warp;to.warpFrames=from.warpFrames;for(LoopEngine.Layer l:from.layers){LoopEngine.Layer n=l.copy();n.start=l.start;n.end=l.end;n.mode=l.mode;n.stretch=l.stretch;n.pitch=l.pitch;n.cutoff=l.cutoff;n.gain=l.gain;n.pan=l.pan;n.reverse=l.reverse;n.mute=l.mute;n.solo=l.solo;to.layers.add(n);}to.period=from.cycle();}return e;}
    public static void export(LoopEngine snapshot,OutputStream stream)throws IOException{int frames=0;for(LoopEngine.Layer l:snapshot.banks[0].layers)frames=Math.max(frames,l.frames());if(snapshot.banks[0].warp)frames=snapshot.banks[0].warpFrames;OutputStream out=new BufferedOutputStream(stream);out.write(new byte[]{'R','I','F','F'});integer(out,48+frames*8);out.write(new byte[]{'W','A','V','E','f','m','t',' '});integer(out,16);shortInt(out,3);shortInt(out,2);integer(out,LoopEngine.RATE);integer(out,LoopEngine.RATE*8);shortInt(out,8);shortInt(out,32);out.write(new byte[]{'f','a','c','t'});integer(out,4);integer(out,frames);out.write(new byte[]{'d','a','t','a'});integer(out,frames*8);float[] block=new float[512];byte[] bytes=new byte[2048];for(int at=0;at<frames;at+=256){int n=Math.min(256,frames-at);snapshot.process(null,2,0,1,block,n);ByteBuffer b=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);for(int i=0;i<n*2;i++)b.putFloat(block[i]);out.write(bytes,0,n*8);}out.flush();}
}
